def compressir_repeticiones(texto: str) -> str:
    if not texto:
        return ""
    result = []
    count = 1
    for i in range(1, len(texto)):
        if texto[i] == texto[i-1]:
            count += 1
        else:
            result.append(texto[i-1] + str(count))
            count = 1
    # add the last group
    result.append(texto[-1] + str(count))
    return "".join(result)

def iniciales(nombre: str) -> str:
    """
    Return the first letter of each word in `nombre`, converted to uppercase,
    concatenated into a single string. Words are separated by any whitespace.
    Hyphens within a word do not split it.
    """
    words = nombre.split()
    if not words:
        return ""
    return ''.join(word[0].upper() for word in words)

def aplanar(datos: list) -> list:
    def flatten(item):
        if isinstance(item, (list, tuple)):
            result = []
            for sub in item:
                result.extend(flatten(sub))
            return result
        else:
            return [item]

    result = []
    for element in datos:
        result.extend(flatten(element))
    return result

import csv
import io

def parsear_ventas(texto: str) -> list[dict]:
    if not texto or not texto.strip():
        return []

    reader = csv.reader(io.StringIO(texto))
    rows = [row for row in reader if row]

    if not rows:
        return []

    expected_header = ['fecha', 'producto', 'cantidad', 'precio']
    header = rows[0]
    if header != expected_header:
        raise ValueError(f"Cabecera no es la indicada: esperada {expected_header}")

    result = []
    for row in rows[1:]:
        if len(row) != 4:
            raise ValueError(f"Fila tiene {len(row)} campos, se esperan 4: {row}")
        fecha, producto, cantidad_str, precio_str = row
        fecha = fecha.strip()
        producto = producto.strip()
        cantidad_str = cantidad_str.strip()
        precio_str = precio_str.strip()

        try:
            cantidad = int(cantidad_str)
        except ValueError:
            raise ValueError(f"Cantidad '{cantidad_str}' no es un entero")
        if cantidad < 0:
            raise ValueError(f"Cantidad '{cantidad_str}' es negativa")

        try:
            precio = float(precio_str)
        except ValueError:
            raise ValueError(f"Precio '{precio_str}' no es un número")

        result.append({
            'fecha': fecha,
            'producto': producto,
            'cantidad': cantidad,
            'precio': precio
        })

    return result

import datetime

def parsear_fecha(texto: str) -> str:
    texto = texto.strip()
    # Formato 1: AAAA-MM-DD
    if '-' in texto:
        parts = texto.split('-')
        if len(parts) == 3 and len(parts[0]) == 4 and len(parts[1]) == 2 and len(parts[2]) == 2:
            if parts[0].isdigit() and parts[1].isdigit() and parts[2].isdigit():
                try:
                    datetime.date(int(parts[0]), int(parts[1]), int(parts[2]))
                except ValueError:
                    raise ValueError(f"Fecha inválida: {texto}")
                return texto
    # Formato 2: DD/MM/AAAA
    elif '/' in texto:
        parts = texto.split('/')
        if len(parts) == 3 and len(parts[0]) == 2 and len(parts[1]) == 2 and len(parts[2]) == 4:
            if parts[0].isdigit() and parts[1].isdigit() and parts[2].isdigit():
                day = int(parts[0])
                month = int(parts[1])
                year = int(parts[2])
                try:
                    datetime.date(year, month, day)
                except ValueError:
                    raise ValueError(f"Fecha inválida: {texto}")
                return f"{year}-{month:02d}-{day:02d}"
    # Formato 3: D de MES de AAAA
    elif " de " in texto:
        tokens = texto.split()
        if len(tokens) != 5:
            raise ValueError(f"Formato no reconocido: {texto}")
        day_str = tokens[0].strip()
        month_token = tokens[2].strip()
        year_str = tokens[4].strip()
        if not day_str.isdigit():
            raise ValueError(f"Día inválido: {day_str}")
        day = int(day_str)
        month_map = {
            "enero": 1,
            "febrero": 2,
            "marzo": 3,
            "abril": 4,
            "mayo": 5,
            "junio": 6,
            "julio": 7,
            "agosto": 8,
            "septiembre": 9,
            "octubre": 10,
            "noviembre": 11,
            "diciembre": 12,
        }
        if month_token.lower() not in month_map:
            raise ValueError(f"Mes inválido: {month_token}")
        month = month_map[month_token.lower()]
        try:
            datetime.date(int(year_str), month, day)
        except ValueError:
            raise ValueError(f"Fecha inválida: {texto}")
        return f"{int(year_str)}-{month:02d}-{day:02d}"
    else:
        raise ValueError(f"Formato no reconocido: {texto}")

def promedio_movil(valores: list[float], ventana: int) -> list[float]:
    if ventana <= 0 or ventana > len(valores):
        return []
    resultado = []
    for i in range(len(valores) - ventana + 1):
        resultado.append(sum(valores[i:i + ventana]) / ventana)
    return resultado

def mochila(pesos: list[int], valores: list[int], capacidad: int) -> tuple[int, list[int]]:
    if len(pesos) != len(valores):
        raise ValueError("Lengths of pesos and valores must be equal")
    n = len(pesos)
    if n == 0:
        return (0, [])
    if any(p < 0 for p in pesos):
        raise ValueError("Weights must be non-negative")
    if capacidad < 0:
        raise ValueError("Capacity must be non-negative")
    best = None
    for mask in range(1 << n):
        total_weight = 0
        total_value = 0
        indices = []
        for i in range(n):
            if mask & (1 << i):
                total_weight += pesos[i]
                total_value += valores[i]
                indices.append(i)
        if total_weight <= capacidad:
            if best is None:
                best = (total_value, total_weight, indices)
            else:
                b_val, b_weight, b_indices = best
                if total_value > b_val:
                    best = (total_value, total_weight, indices)
                elif total_value == b_val:
                    if total_weight < b_weight:
                        best = (total_value, total_weight, indices)
                    elif total_weight == b_weight:
                        if len(indices) < len(b_indices):
                            best = (total_value, total_weight, indices)
                        elif len(indices) == len(b_indices):
                            if indices < b_indices:
                                best = (total_value, total_weight, indices)
    if best is None:
        return (0, [])
    else:
        return (best[0], best[2])

def evaluar(expresion: str) -> int:
    if '/' in expresion or '**' in expresion:
        raise ValueError("Unsupported operator")
    if not expresion.strip():
        raise ValueError("Empty expression")
    try:
        result = eval(expresion)
    except ZeroDivisionError:
        raise ZeroDivisionError("Division by zero")
    except SyntaxError:
        raise ValueError("Invalid syntax")
    except Exception:
        raise ValueError("Invalid expression")
    return result

from collections import OrderedDict

class CacheLRU:
    def __init__(self, capacidad: int):
        if capacidad < 0:
            raise ValueError("Capacity cannot be negative")
        self.capacidad = capacidad
        self._datos = OrderedDict()

    def get(self, clave):
        if clave in self._datos:
            self._datos.move_to_end(clave)
            return self._datos[clave]
        return None

    def put(self, clave, valor):
        if self.capacidad == 0:
            return
        if clave in self._datos:
            self._datos[clave] = valor
            self._datos.move_to_end(clave)
        else:
            if len(self._datos) >= self.capacidad:
                self._datos.popitem(last=False)
            self._datos[clave] = valor
            self._datos.move_to_end(clave)

    def __len__(self):
        return len(self._datos)
